package br.com.loja.product;import br.com.loja.product.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController{private final ProductRepository repo;public ProductController(ProductRepository r){repo=r;}@GetMapping public List<Product> catalog(){return repo.findByActiveTrueOrderByName();}@GetMapping("/admin") @PreAuthorize("hasRole('ADMIN')") public List<Product> all(){return repo.findAll();}@PostMapping @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.CREATED) public Product create(@Valid @RequestBody ProductRequest q){repo.findBySkuIgnoreCase(q.sku()).ifPresent(x->{throw new ResponseStatusException(HttpStatus.CONFLICT,"SKU já cadastrado");});return repo.save(new Product(null,q.sku(),q.name(),q.description(),q.category(),q.price(),q.stock(),q.active()==null||q.active()));}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public Product update(@PathVariable Long id,@Valid @RequestBody ProductRequest q){Product p=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Produto não encontrado"));p.setSku(q.sku());p.setName(q.name());p.setDescription(q.description());p.setCategory(q.category());p.setPrice(q.price());p.setStock(q.stock());if(q.active()!=null)p.setActive(q.active());return repo.save(p);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.deleteById(id);}}
